-- Collect the placeholder serialized_equipment ids into a temp table so we
-- only compute it once and can reference it from every cleanup step.
CREATE TEMP TABLE _placeholder_se ON COMMIT DROP AS
SELECT id FROM serialized_equipment
 WHERE product_id IN (SELECT id FROM products WHERE part_number IN ('TRL-AIR-12', 'TRL-AIR-24'));

-- Null out the optional references first so deletes don't trip NOT NULL or FK.
UPDATE ticket_line_items
   SET equipment_id_installed = NULL
 WHERE equipment_id_installed IN (SELECT id FROM _placeholder_se);

UPDATE ticket_line_items
   SET equipment_id_removed = NULL
 WHERE equipment_id_removed IN (SELECT id FROM _placeholder_se);

UPDATE shop_work_order_items
   SET serialized_equipment_id = NULL
 WHERE serialized_equipment_id IN (SELECT id FROM _placeholder_se);

UPDATE serialized_equipment
   SET parent_equipment_id = NULL
 WHERE parent_equipment_id IN (SELECT id FROM _placeholder_se);

-- Delete the required-FK children.
DELETE FROM rental_agreement_items
 WHERE serialized_equipment_id IN (SELECT id FROM _placeholder_se);

DELETE FROM repair_orders
 WHERE serialized_equipment_id IN (SELECT id FROM _placeholder_se);

-- Delete the placeholder serialized equipment, assembly components, and products.
DELETE FROM serialized_equipment
 WHERE id IN (SELECT id FROM _placeholder_se);

DELETE FROM assembly_components
 WHERE assembly_product_id  IN (SELECT id FROM products WHERE part_number IN ('TRL-AIR-12', 'TRL-AIR-24'))
    OR component_product_id IN (SELECT id FROM products WHERE part_number IN ('TRL-AIR-12', 'TRL-AIR-24'));

DELETE FROM products WHERE part_number IN ('TRL-AIR-12', 'TRL-AIR-24');

-- Upsert the real trailer products + the 30-min SCBA cylinder product used
-- as the cylinder child. Values mirror server/prisma/seed.ts.
                      default_rental_rate_daily, default_rental_rate_weekly, default_rental_rate_monthly,
                      is_serialized, is_assembly, is_taxable, qb_item_full_name,
                      is_active, created_at, updated_at)
VALUES
  (gen_random_uuid(), 'TRL-2400', 'Basin 2400 PSI Supplied Air Trailer',
   'assembly', 'rental', 'EA', 225, 1125, 3500,
   TRUE, TRUE, TRUE, 'Rentals:2400 PSI Air Trailer', TRUE, now(), now()),
  (gen_random_uuid(), 'TRL-4500', 'Basin 4500 PSI Supplied Air Trailer',
   'assembly', 'rental', 'EA', 275, 1375, 4500,
   TRUE, TRUE, TRUE, 'Rentals:4500 PSI Air Trailer', TRUE, now(), now()),
  (gen_random_uuid(), 'AIR-TANK-30', 'Breathable Air Tank',
   'supplied_air_component', 'both', 'EA', NULL, NULL, NULL,
   TRUE, FALSE, TRUE, 'Air Supply:30-Min SCBA Cylinder', TRUE, now(), now())
ON CONFLICT (part_number) DO UPDATE
  SET name              = EXCLUDED.name,
      category          = EXCLUDED.category,
